#!/usr/bin/env python3
"""Generates src/decoders/modern/aac/sauti_aac_sbr_ld_table.c and include/sauti_aac_sbr_ld_table.h: the prototype filters of the LOW-DELAY complex QMF (CLDFB) of AAC-LD / AAC-ELD with the
low-delay SBR tool (the 320 coefficients of the 32-band bank and the 640 coefficients of the 64-band synthesis of the dual rate), read from the source of libxaac (https://github.com/ittiam-systems/libxaac, Apache License 2.0, Copyright (C) 2018 The Android Open Source Project, originally developed and contributed by
Ittiam Systems Pvt. Ltd): the table `qmf_c_eld3` of decoder/ixheaacd_sbr_rom.c, 640 entries of which the second half repeats the first (checked here), 16-bit fixed point, the value 32768 = 1.0 of the
analysis window scaled by 64 (the analysis window of the filter bank is `value / 64` in the integer units of that decoder; see docs/AAC_FAMILY_ASM.md SBR-131).  Data only: no code of the decoder is used.
The licence text and NOTICE of libxaac are in third_party/libxaac/.  usage: tools/gen_sbr_ld_qmf_table.py [LIBXAAC_DIR]   (default ~/Sauti-tools/libxaac; read-only, the checkout stays outside the repository)"""
import os, re, sys
ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), '..'))
XAAC = os.path.expanduser(sys.argv[1] if len(sys.argv) > 1 else '~/Sauti-tools/libxaac')
src = open(os.path.join(XAAC, 'decoder', 'ixheaacd_sbr_rom.c'), errors='replace').read()
m = re.search(r'//\s*WORD16 qmf_c_eld3\[640\];\s*\n\s*\{(.*?)\},', src, re.S)
v = [int(x) for x in re.findall(r'-?\d+', m.group(1))]
assert len(v) == 640 and v[:320] == v[320:], 'unexpected table'
w = v[:320]
m64 = re.search(r'//\s*WORD16 qmf_c_eld\[640\];\s*\n\s*\{(.*?)\},', src, re.S)
w64 = [int(x) for x in re.findall(r'-?\d+', m64.group(1))]
assert len(w64) == 640 and max(i for i, x in enumerate(w64) if x) == 543, 'unexpected 64-band table'
lines = []
for i in range(0, 320, 10): lines.append('    ' + ', '.join('%d' % x for x in w[i:i + 10]) + ',')
lines64 = []
for i in range(0, 640, 10): lines64.append('    ' + ', '.join('%d' % x for x in w64[i:i + 10]) + ',')
open(os.path.join(ROOT, 'src/decoders/modern/aac/sauti_aac_sbr_ld_table.c'), 'w').write(
    '/* GENERATED by tools/gen_sbr_ld_qmf_table.py from libxaac (Apache License 2.0, see third_party/libxaac/NOTICE): tables qmf_c_eld3 (first 320 of 640 entries, the second half repeats the first) and qmf_c_eld (640 entries) of decoder/ixheaacd_sbr_rom.c. */\n'
    '#include "sauti_aac_sbr_ld_table.h"\n\nconst int16_t sauti_aac_sbr_ld_qmf_window[320] = {\n' + '\n'.join(lines) + '\n};\n\nconst int16_t sauti_aac_sbr_ld_qmf_window64[640] = {\n' + '\n'.join(lines64) + '\n};\n')
open(os.path.join(ROOT, 'include/sauti_aac_sbr_ld_table.h'), 'w').write(
    '#ifndef SAUTI_AAC_SBR_LD_TABLE_H\n#define SAUTI_AAC_SBR_LD_TABLE_H\n#include <stdint.h>\n/* Prototype filter of the low-delay QMF (CLDFB) of AAC-LD / AAC-ELD SBR: 320 coefficients (decoder units: window = value / 64, i.e. 2^-6 of the 16-bit value), the\n * data of libxaac qmf_c_eld3 (generated by tools/gen_sbr_ld_qmf_table.py; Apache License 2.0, third_party/libxaac/NOTICE). */\nextern const int16_t sauti_aac_sbr_ld_qmf_window[320];\n/* The prototype of the 64-band synthesis of the dual rate: 640 coefficients (544 nonzero), same units (libxaac qmf_c_eld). */\nextern const int16_t sauti_aac_sbr_ld_qmf_window64[640];\n#endif\n')
print('ok', len(w), 'max', max(w), 'last nonzero', max(i for i, x in enumerate(w) if x))
